// 단위. 계산만
expect(total([{ price: 1000, n: 2 }])).toBe(2000);

// 통합. 저장소까지 진짜로
await cart.add({ id: 'a', price: 1000, n: 2 });
expect(await cart.total()).toBe(2000);

// E2E. 브라우저에서 사용자가 하듯이
await page.click('[data-act="add"]');
await expect(page.locator('.total')).toHaveText('2,000원');

// A 모듈. 문자열로 준다 (테스트 초록)
export function getPrice() { return '1000'; }

// B 모듈. 숫자를 기대한다 (테스트 초록, 가짜로 1000 을 넣었으니까)
export function withTax(price) { return price * 1.1; }

// 붙이면: '1000' * 1.1 = 1100 (우연히 동작) ...이지만
//         '1000' + 100  = '1000100'  ← 다른 자리에서 터진다
// 통합 테스트가 진짜 A 를 B 에 붙여 보면 즉시 드러난다

